package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.compliance.*;
import static org.assertj.core.api.Assertions.*;
import java.math.BigDecimal;import java.time.LocalDate;
import org.junit.jupiter.api.Test;
class WorkforceLeaveComplianceRulesTest {
 @Test void referenceHasEditableParametersAndOfficialSources(){var p=ComplianceReference.singapore();assertThat(p.rules().annualDays()).containsExactly(7,8,9,10,11,12,13,14);assertThat(p.sources()).hasSizeGreaterThanOrEqualTo(8);ComplianceRules.validate(p.rules());assertThat(p.sources()).allMatch(s->s.url().startsWith("https://"));}
 @Test void hourlyPayDoesNotDeterminePartTime(){var r=ComplianceReference.singapore().rules();assertThat(ComplianceRules.partTime(r,new BigDecimal("34"))).isTrue();assertThat(ComplianceRules.partTime(r,new BigDecimal("35"))).isFalse();}
 @Test void annualServiceAndPartTimeUnitsAreSeparate(){var r=ComplianceReference.singapore().rules();var h=LocalDate.of(2026,1,1);var full=LeaveEntitlement.annual(r,h,LocalDate.of(2026,4,1),new BigDecimal("44"),new BigDecimal("44"),new BigDecimal("8"));assertThat(full.unit()).isEqualTo("day");assertThat(full.annual()).isEqualByComparingTo("7");assertThat(full.earned()).isEqualByComparingTo("2");var part=LeaveEntitlement.annual(r,h,LocalDate.of(2026,4,1),new BigDecimal("20"),new BigDecimal("44"),new BigDecimal("8"));assertThat(part.unit()).isEqualTo("hour");assertThat(part.annual()).isEqualByComparingTo("25.5");assertThat(part.earned()).isEqualByComparingTo("6.4");assertThat(LeaveEntitlement.annual(r,h,LocalDate.of(2034,1,1),new BigDecimal("44"),new BigDecimal("44"),new BigDecimal("8")).annual()).isEqualByComparingTo("14");}
 @Test void hospitalAndOutpatientShareCap(){var r=ComplianceReference.singapore().rules();var e=LeaveEntitlement.sick(r,6,new BigDecimal("44"),new BigDecimal("44"),new BigDecimal("8"));assertThat(e.outpatient()).isEqualByComparingTo("14");assertThat(e.hospitalTotal()).isEqualByComparingTo("60");assertThat(e.remainingHospital(new BigDecimal("14"),new BigDecimal("0"))).isEqualByComparingTo("46");assertThat(LeaveEntitlement.sick(r,3,new BigDecimal("44"),new BigDecimal("44"),new BigDecimal("8")).hospitalTotal()).isEqualByComparingTo("15");}
 @Test void partTimeExtraWorkSplitsOrdinaryAndPremium(){var r=ComplianceReference.singapore().rules();var s=WorkHoursPolicy.split(r,9*3600,4*3600,8*3600,0,44*3600,true);assertThat(s.normalSeconds()).isEqualTo(4*3600);assertThat(s.additionalSeconds()).isEqualTo(4*3600);assertThat(s.overtimeSeconds()).isEqualTo(3600);}
 @Test void calendarAccrualExcludesApprovedUnpaidDaysAndRetainsEligibility(){var r=ComplianceReference.singapore().rules();var start=LocalDate.of(2026,1,1);var days=new java.util.HashMap<LocalDate,BigDecimal>();for(int m=1;m<=4;m++)days.put(LocalDate.of(2026,m,15),BigDecimal.ONE);var normal=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2026,4,30),new BigDecimal("20"),new BigDecimal("44"),new BigDecimal("8"));var excluded=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2026,4,30),new BigDecimal("20"),new BigDecimal("44"),new BigDecimal("8"),days);assertThat(normal.earned()).isEqualByComparingTo("8.5");assertThat(excluded.earned()).isEqualByComparingTo("6.4");var full=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2026,12,31),new BigDecimal("44"),new BigDecimal("44"),new BigDecimal("8"));assertThat(full.earned()).isEqualByComparingTo("7");}
 @Test void encashmentUsesGrossDailyAndNeverOvertimeMultiplier(){assertThat(LeaveEncashmentRate.monthly(new BigDecimal("3300"),new BigDecimal("5"),new BigDecimal("2"))).isEqualByComparingTo("304.62");}
 @Test void adoptedPartTimeContractPaysAdditionalOrdinaryHoursAndMandatoryPremium(){
 var r=ComplianceReference.singapore();var id=java.util.UUID.randomUUID();var c=new ComplianceDtos.Contract(id,id,id,1,LocalDate.of(2026,1,1),LocalDate.of(2026,1,1),id,1,new BigDecimal("4"),new BigDecimal("20"),new BigDecimal("5"),new BigDecimal("8"),new BigDecimal("44"),"non_workman","Reviewed",true);var p=new ComplianceDtos.Policy(id,1,r.name(),LocalDate.of(2026,1,1),LocalDate.of(2026,12,31),"published",r.rules(),r.sources(),id);var terms=new ComplianceEvidence.Terms(c,p);var calc=new com.rpb.reservation.workforce.payroll.PayCalculator();var result=calc.calculate(new com.rpb.reservation.workforce.payroll.PayCalculator.Rule("hourly",new BigDecimal("10"),new BigDecimal("4"),new BigDecimal("20"),false,BigDecimal.ONE),java.util.List.of(new com.rpb.reservation.workforce.payroll.PayCalculator.WorkDay(LocalDate.of(2026,11,2),9*3600,0,true)),new com.rpb.reservation.workforce.payroll.PayCalculator.Units(null,null),java.util.List.of(),java.util.List.of(),terms);assertThat(result.basicPay()).isEqualByComparingTo("80");assertThat(result.overtimePay()).isEqualByComparingTo("15");assertThat(result.grossPay()).isEqualByComparingTo("95");assertThat(result.overtimeSeconds()).isEqualTo(3600);
 }
 @Test void unpaidServiceMonthDoesNotReappearAsLateCreditInFollowingCalendarYear(){var r=ComplianceReference.singapore().rules();var start=LocalDate.of(2026,1,1);var days=java.util.Map.of(LocalDate.of(2026,12,1),BigDecimal.ONE);var next=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2027,1,1),new BigDecimal("40"),new BigDecimal("44"),new BigDecimal("8"),days);assertThat(next.earned()).isZero();}
 @Test void serviceYearRoundingIsConservedAcrossCalendarAccounts(){var r=ComplianceReference.singapore().rules();var start=LocalDate.of(2026,3,14);var a=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2026,12,31),new BigDecimal("40"),new BigDecimal("44"),new BigDecimal("8"));var b=LeaveEntitlement.calendarAnnual(r,start,LocalDate.of(2027,3,13),new BigDecimal("40"),new BigDecimal("44"),new BigDecimal("8"));assertThat(a.earned().add(b.earned())).isEqualByComparingTo("7");}
}
